import{_ as a,I as r,f as i,i as s}from"./chunks/framework.CzIb_Ns1.js";const b=JSON.parse('{"title":"OneUI","description":"","frontmatter":{},"headers":[],"relativePath":"OS/OneUI.md","filePath":"OS/OneUI.md"}'),t={name:"OS/OneUI.md"};function o(n,e,p,l,d,c){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="oneui" tabindex="-1">OneUI <a class="header-anchor" href="#oneui" aria-label="Permalink to “OneUI”">​</a></h1><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to “”">​</a></h2><h3 id="步骤1-下载原包" tabindex="-1">步骤1 - 下载原包: <a class="header-anchor" href="#步骤1-下载原包" aria-label="Permalink to “步骤1 - 下载原包:”">​</a></h3><p><a href="https://samfw.com/" target="_blank" rel="noreferrer">https://samfw.com/</a> 下载后找到压缩包里 AP_ 开头的文件,以压缩文件打开,找到 super.img.lz4 这里面有我们要的分区</p><h3 id="步骤2-更换init三件套" tabindex="-1">步骤2 - 更换init三件套: <a class="header-anchor" href="#步骤2-更换init三件套" aria-label="Permalink to “步骤2 - 更换init三件套:”">​</a></h3><p>将附件中同Android版本的init三件套替换入解包后的 system 中</p><h3 id="步骤3-处理selinux" tabindex="-1">步骤3 - 处理SELinux: <a class="header-anchor" href="#步骤3-处理selinux" aria-label="Permalink to “步骤3 - 处理SELinux:”">​</a></h3><p>/product/etc/selinux/mapping /system_ext/etc/selinux/mapping 删除 mapping 文件夹中的所有文件</p><h3 id="步骤4-删除-fabric-crypto-相关文件" tabindex="-1">步骤4 - 删除 fabric_crypto 相关文件: <a class="header-anchor" href="#步骤4-删除-fabric-crypto-相关文件" aria-label="Permalink to “步骤4 - 删除 fabric_crypto 相关文件:”">​</a></h3><p>在 system 分区内搜索 fabric_crypto 把搜索到的全部删除</p><h3 id="步骤5-移除-ro-frp-pst-条目" tabindex="-1">步骤5 - 移除 ro.frp.pst 条目: <a class="header-anchor" href="#步骤5-移除-ro-frp-pst-条目" aria-label="Permalink to “步骤5 - 移除 ro.frp.pst 条目:”">​</a></h3><p>/product/etc/build.prop 删除 ro.frp.pst 条目</p><h3 id="步骤6-替换-passwd-group-文件" tabindex="-1">步骤6 - 替换 passwd group 文件: <a class="header-anchor" href="#步骤6-替换-passwd-group-文件" aria-label="Permalink to “步骤6 - 替换 passwd group 文件:”">​</a></h3><p>将原包 vendor 分区中的 passwd group 替换到自己 vendor 里</p><h3 id="步骤7-禁用-knox-服务" tabindex="-1">步骤7 - 禁用 knox 服务: <a class="header-anchor" href="#步骤7-禁用-knox-服务" aria-label="Permalink to “步骤7 - 禁用 knox 服务:”">​</a></h3><p>ro.config.knox=false ro.config.dmverity=false 追加到可生效 build.prop 末尾</p><h3 id="步骤8-删除可能导致卡二-软重启的文件或build" tabindex="-1">步骤8 - 删除可能导致卡二/软重启的文件或build: <a class="header-anchor" href="#步骤8-删除可能导致卡二-软重启的文件或build" aria-label="Permalink to “步骤8 - 删除可能导致卡二/软重启的文件或build:”">​</a></h3><p>/vendor/overlay /system_ext/priv-app/com.qualcomm.location 删除上述文件夹 /system/build.prop 删除 media.settings.xml=/vendor/etc/media_profiles_vendor.xml 条目</p><h3 id="步骤9-补齐vndk" tabindex="-1">步骤9 - 补齐vndk: <a class="header-anchor" href="#步骤9-补齐vndk" aria-label="Permalink to “步骤9 - 补齐vndk:”">​</a></h3><p>不知道补多少的把附件里的全补到 /system_ext/apex 并补齐 vintf</p><h3 id="步骤10-补齐调试build" tabindex="-1">步骤10 - 补齐调试build: <a class="header-anchor" href="#步骤10-补齐调试build" aria-label="Permalink to “步骤10 - 补齐调试build:”">​</a></h3><p>persist.sys.disable_rescue=true persist.logd.audit.rate=65535 persist.sys.usb.config=mtp,adb ro.adb.secure=0 ro.secure=0 ro.debuggable=1 persist.service.adb.enable=1 ro.sys.sdcardfs=0 ro.apex.updatable=true 追加到可生效 build.prop 末尾</p><h2 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to “”">​</a></h2><h3 id="静态分区额外处理" tabindex="-1">静态分区额外处理: <a class="header-anchor" href="#静态分区额外处理" aria-label="Permalink to “静态分区额外处理:”">​</a></h3><p>/system/build.prop 删除 ro.actionable_compatible_property.enabled=true 条目</p><p>ro.build.system_root_image=true ro.support_one_handed_mode=true persist.sys.binary_xml=false persist.logd.logpersistd.buffer=0 ro.opengles.version=196610 persist.sys.disable_rescue=true ro.control_privapp_permissions=disable ro.cp_system_other_odex=0 ro.nnapi.extensions.deny_on_product=true ro.boot.slot_suffix=a 追加到可生效build.prop末尾</p><p>/system/etc/init 删除 cppreopts.rc otapreopt.rc update_verifier.rc recovery-persist.rc recovery-refresh.rc</p>',27)])])}const u=a(t,[["render",o]]);export{b as __pageData,u as default};
